<div class="page-heading"><div><div class="eyebrow">Ruang kerja</div><h1>Antrean permohonan</h1><p>Cari berdasarkan nomor atau pemohon, lalu saring berdasarkan layanan, status, dan tanggal masuk.</p></div><?php if ($this->metro->can($current_user->id,'requests.create_offline')): ?><a class="button primary" href="<?= site_url('petugas/permohonan/baru') ?>">+ Input permohonan loket</a><?php endif; ?></div>

<?php if ($selected_applicant): ?><div class="alert success">Riwayat permohonan: <strong><?= e($selected_applicant->full_name) ?></strong> · <a href="<?= site_url('petugas/pemohon') ?>">Kembali ke data pemohon</a></div><?php endif; ?>
<form class="card filter-card" method="get" action="<?= site_url('petugas/permohonan') ?>"><input type="hidden" name="bucket" value="<?= e($filters['bucket']) ?>"><div class="filter-grid">
<?php if ($selected_applicant): ?><input type="hidden" name="pemohon" value="<?= (int) $selected_applicant->id ?>"><?php endif; ?>
<label>Cari permohonan<input type="search" name="q" value="<?= e($query) ?>" placeholder="Nomor, nama, atau instansi"></label>
<label>Status unit / permohonan<select name="status"><option value="">Semua status</option><?php foreach ($valid_status as $code): ?><option value="<?= e($code) ?>"<?= $filters['status'] === $code ? ' selected' : '' ?>><?= e($code === 'verification' ? 'Perlu verifikasi' : status_label($code)) ?></option><?php endforeach; ?></select></label>
<label>Layanan<select name="service_type"><option value="">Semua layanan</option><?php foreach ($service_types as $service_type): ?><option value="<?= e($service_type->option_code) ?>"<?= $filters['service_type'] === $service_type->option_code ? ' selected' : '' ?>><?= e($service_type->option_label) ?></option><?php endforeach; ?></select></label>
<label>Dari tanggal<input type="date" name="date_from" value="<?= e($filters['date_from']) ?>"></label><label>Sampai tanggal<input type="date" name="date_to" value="<?= e($filters['date_to']) ?>"></label>
<button class="button primary" type="submit">Terapkan</button></div></form>
<section class="card table-card"><div class="filter-results"><span><strong><?= (int)$pagination['total'] ?></strong> permohonan ditemukan</span><a href="<?= site_url('petugas/permohonan') ?>">Hapus filter</a></div>
<?php if ($requests): ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Nomor permohonan</th><th>Pemohon</th><th>Layanan</th><th><?= $filters['status'] && $filters['status'] !== 'in_progress' ? 'Unit sesuai filter' : 'Unit' ?></th><th>Status</th><th>Tanggal masuk</th><th>Penera</th><th></th></tr></thead><tbody><?php foreach ($requests as $r): ?><tr class="clickable-row" tabindex="0" data-row-url="<?= site_url('petugas/permohonan/'.$r->id) ?>"><td data-label="Nomor"><strong><?= e($r->request_no) ?></strong></td><td data-label="Pemohon"><strong><?= e($r->full_name) ?></strong><small><?= e($r->organization_name) ?></small></td><td data-label="Layanan"><?= e(master_label('service_type',$r->service_type)) ?></td><td data-label="<?= $filters['status'] && $filters['status'] !== 'in_progress' ? 'Unit sesuai filter' : 'Unit' ?>"><?= (int) $r->unit_count ?> unit</td><td data-label="Status"><span class="badge <?= status_class($r->request_status) ?>"><?= e(status_label($r->request_status)) ?></span></td><td data-label="Masuk"><?= e(tanggal_id($r->submitted_at)) ?><small><?= e(date('H:i', strtotime($r->submitted_at))) ?> WIB</small></td><td data-label="Penera"><?= e($r->penera_display ?: '—') ?></td><td data-label="Aksi"><a class="table-link" href="<?= site_url('petugas/permohonan/' . $r->id) ?>">Buka →</a></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="table-empty"><strong>Tidak ada permohonan yang cocok</strong>Coba ubah kata kunci atau filter.</div><?php endif; ?>
<?= metro_pager($pagination,'petugas/permohonan',array_filter(array('bucket'=>$filters['bucket'],'q'=>$query,'status'=>$filters['status'],'service_type'=>$filters['service_type'],'date_from'=>$filters['date_from'],'date_to'=>$filters['date_to'],'pemohon'=>$filters['applicant_id']),'strlen')) ?></section>
